package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null ? null : request.name();
        String grade = request == null ? null : request.grade();
        if (name == null || name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (grade == null || !GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        // Stored without surrounding spaces.
        body.set(new PersonRequest(name.strip(), grade, request.version()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuses adding a person with a name already used on the sheet (ignoring case). */
public class CheckPersonName {
    public void check(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository) throws InvalidPersonException {
        if (repository.nameInUse(sheetId, request.name(), null)) {
            throw new InvalidPersonException("That name is already in use on this sheet.");
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class CreatePerson {
    public void create(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository, Out<Person> person) {
        person.set(repository.create(sheetId, request.name(), request.grade()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the added person once every rule has passed and it is stored. */
public class AuditPersonAdded {
    public void audit(@Val Person person, @RequestParam(value = "user", required = false) String user, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.getGrade());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class RespondWithPersonCreated {
    public void respond(@Val Person person, ObjectResponse<ResponseEntity<PersonResponse>> response) {
        response.send(new ResponseEntity<>(PersonResponse.from(person), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPerson {
    public void handle(@Parameter InvalidPersonException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
